def findKthNumber(n: int, k: int) -> int:
    def dfs(current, k):
        count = 0
        cur = current
        next_node = current + 1
        while cur <= n:
            count += min(n + 1, next_node) - cur
            if count >= k:
                return dfs(cur, k)
            cur *= 10
            next_node *= 10
            k -= count
        return current

    return dfs(1, k)
